                } catch (error: any) {
                    const errStr = error.message || String(error);
                    if ((errStr.includes("403") || errStr.includes("PERMISSION_DENIED") || errStr.includes("404")) && modelToUse !== 'gemini-2.5-flash') {
                        console.warn(`Model ${modelToUse} failed with permission error. Falling back to gemini-2.5-flash.`);
                        const fallbackResponse = await ai.models.generateContent({ 
                            model: 'gemini-2.5-flash', 
                            contents: allContents, 
                            config 
                        });
                        const fallbackText = fallbackResponse.text;
                        if (!fallbackText) throw new Error("Empty response from fallback model.");
                        modelResponse = { role: 'model', text: fallbackText, fromSkill: skill };
                        if (skill === 'docGen') {
                            modelResponse.pdfContent = fallbackText;
                            modelResponse.text = `Here is the document draft (Standard Mode) for: "${prompt}"`;
                        }
                    } else {
                        throw error;
                    }
                }
            }

            if (modelResponse) {
                await addDoc(historyRef, { ...modelResponse, timestamp: serverTimestamp() });
            }
        } catch (error: any) {
            console.error("Error in NovaScreen:", error);

            let userFriendlyError = "My apologies, I'm having trouble connecting. Let's try that again in a moment.";
            const errorString = error.message || String(error) || JSON.stringify(error);
            if (errorString.includes("429") || errorString.includes("quota") || errorString.includes("RESOURCE_EXHAUSTED")) {
                userFriendlyError = "I'm receiving too many messages at once. Please give me a moment to catch up.";
            } else if (errorString.includes("Empty response")) {
                userFriendlyError = "I couldn't generate a response for that. Please try rephrasing.";
            } else if (errorString.includes("403") || errorString.includes("PERMISSION_DENIED")) {
                userFriendlyError = "I'm unable to access the requested AI model with your current plan. Please try a simpler request.";
            }

            setApiError(userFriendlyError);
            await addDoc(historyRef, { role: 'model', text: userFriendlyError, timestamp: serverTimestamp() });
        } finally {
            setLoading(false);
            setGenerationMessage(null);
        }
    };

    const processUserMessage = async (text: string, file: typeof uploadedFile = null) => {
         if (!userProfile) return;

         const currentSkill = activeSkill;
         setInput('');
         setUploadedFile(null);

         const emotion = await analyzeEmotionWithHuggingFace(text);

        setUserPreferences(prev => {
            const newEmotionCounts = { ...prev.emotionCounts };
            if (emotion) newEmotionCounts[emotion.label] = (newEmotionCounts[emotion.label] || 0) + 1;
            const newMessageCount = prev.messageCount + 1;
            const newTotalLength = (prev.avgUserMessageLength * prev.messageCount) + text.length;

            return {
                ...prev,
                emotionCounts: newEmotionCounts,
                messageCount: newMessageCount,
                avgUserMessageLength: newTotalLength / newMessageCount,
            };
        });

        const userMessage: Omit<NovaMessage, 'id'> = {
            role: 'user',
            text,
            timestamp: serverTimestamp() as Timestamp,
            ...(emotion && { emotion }),
            ...(file?.type === 'image' && { uploadedImageUrl: file.content }),
        };

        const historyRef = collection(db, 'users', userProfile.uid, 'nova_history');
        await addDoc(historyRef, userMessage);

        updateUserMemory(text);

        executeSkill(text, file, currentSkill, emotion);
    }

    const handleSendMessage = async (e: React.FormEvent) => {
        e.preventDefault();
        if ((!input.trim() && !uploadedFile) || loading || !userProfile) return;
        processUserMessage(input, uploadedFile);
    };

    const stopVoiceSession = () => {
        if (sessionPromiseRef.current) {
            sessionPromiseRef.current.then(session => session.close()).catch(e => console.debug("Session close error", e));
        }
        scriptProcessorRef.current?.disconnect();
        mediaStreamSourceRef.current?.disconnect();
        mediaStreamRef.current?.getTracks().forEach(track => track.stop());

        if (inputAudioContextRef.current && inputAudioContextRef.current.state !== 'closed') {
            inputAudioContextRef.current.close().catch(e => console.debug("Input AC close error", e));
        }
        if (outputAudioContextRef.current && outputAudioContextRef.current.state !== 'closed') {
            outputAudioContextRef.current.close().catch(e => console.debug("Output AC close error", e));
        }

        outputSourcesRef.current.forEach(s => s.stop());

        sessionPromiseRef.current = null;
        setVoiceConnectionState('idle');
        setLiveTranscription({userInput: '', modelOutput: ''});
        currentTurnRef.current = {userInput: '', modelOutput: ''};
    };

    const startVoiceSession = async () => {
        if (!userProfile) return;
        setVoiceConnectionState('connecting');
        setApiError(null);

        try {
            const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
            const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            mediaStreamRef.current = stream;

            const inputCtx = new AudioContext({ sampleRate: 16000 });
            const outputCtx = new AudioContext({ sampleRate: 24000 });

            await inputCtx.resume();
            await outputCtx.resume();

            inputAudioContextRef.current = inputCtx;
            outputAudioContextRef.current = outputCtx;

            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
            const systemInstruction = getVoiceSystemInstruction();

            sessionPromiseRef.current = ai.live.connect({
                model: 'gemini-2.5-flash-native-audio-preview-09-2025',
                callbacks: {
                    onopen: () => {
                        setVoiceConnectionState('connected');
                        if (!inputAudioContextRef.current) return;

                        mediaStreamSourceRef.current = inputAudioContextRef.current.createMediaStreamSource(stream);
                        scriptProcessorRef.current = inputAudioContextRef.current.createScriptProcessor(4096, 1, 1);
                        scriptProcessorRef.current.onaudioprocess = (e) => {
                            const inputData = e.inputBuffer.getChannelData(0);
                            sessionPromiseRef.current?.then((s) => s.sendRealtimeInput({ media: createBlob(inputData) }));
                        };
                        mediaStreamSourceRef.current.connect(scriptProcessorRef.current);
                        scriptProcessorRef.current.connect(inputAudioContextRef.current.destination);
                    },
                    onmessage: async (message: LiveServerMessage) => {
                        if (message.toolCall) {
                            for (const fc of message.toolCall.functionCalls) {
                                if (fc.name === 'switchSkill') {
                                    const { skill, prompt } = fc.args;
                                    if (skill && prompt) {
                                        sessionPromiseRef.current?.then((session) => {
                                            session.sendToolResponse({
                                                functionResponses: {
                                                    id : fc.id,
                                                    name: fc.name,
                                                    response: { result: `Action initiated. Task is running in background.` },
                                                }
                                            });
                                        });

                                        let targetSkill: ActiveSkill = 'chat';
                                        const lowerSkill = (skill as string).toLowerCase();
                                        if (lowerSkill.includes('image') || lowerSkill.includes('photo')) targetSkill = 'imageGen';
                                        else if (lowerSkill.includes('video') || lowerSkill.includes('movie')) targetSkill = 'videoGen';
                                        else if (lowerSkill.includes('doc') || lowerSkill.includes('pdf')) targetSkill = 'docGen';
                                        else if (lowerSkill.includes('app') || lowerSkill.includes('code')) targetSkill = 'appGen';
                                        else if (lowerSkill.includes('trend')) targetSkill = 'trends';
                                        else if (lowerSkill.includes('work')) targetSkill = 'workflow';
                                        else if (lowerSkill.includes('scam')) targetSkill = 'scamDetect';

                                        executeSkill(prompt, null, targetSkill);
                                    }
                                }
                            }
                        }

                        if (message.serverContent?.inputTranscription) currentTurnRef.current.userInput += message.serverContent.inputTranscription.text;
                        if (message.serverContent?.outputTranscription) currentTurnRef.current.modelOutput += message.serverContent.outputTranscription.text;
                        setLiveTranscription({ ...currentTurnRef.current });

                        if (message.serverContent?.turnComplete && userProfile) {
                            const fullInput = currentTurnRef.current.userInput;
                            const fullOutput = currentTurnRef.current.modelOutput;
                            currentTurnRef.current = { userInput: '', modelOutput: '' };

                            (async () => {
                                const historyRef = collection(db, 'users', userProfile.uid, 'nova_history');
                                if (fullInput.trim()) {
                                    const emotion = await analyzeEmotionWithHuggingFace(fullInput);

                                    setUserPreferences(prev => {
                                        const newEmotionCounts = { ...prev.emotionCounts };
                                        if (emotion) newEmotionCounts[emotion.label] = (newEmotionCounts[emotion.label] || 0) + 1;
                                        const newMessageCount = prev.messageCount + 1;
                                        const newTotalLength = (prev.avgUserMessageLength * prev.messageCount) + fullInput.length;
                                        return {
                                            ...prev,
                                            emotionCounts: newEmotionCounts,
                                            messageCount: newMessageCount,
                                            avgUserMessageLength: newTotalLength / newMessageCount,
                                        };
                                    });

                                    const userMessagePayload = {
                                        role: 'user' as const,
                                        text: fullInput,
                                        fromSkill: 'voice' as const,
                                        timestamp: serverTimestamp(),
                                        ...(emotion && { emotion }),
                                    };
                                    await addDoc(historyRef, userMessagePayload);
                                    updateUserMemory(fullInput);
                                }
                                if (fullOutput.trim()) {
                                    await addDoc(historyRef, { role: 'model', text: fullOutput, fromSkill: 'voice', timestamp: serverTimestamp() });
                                }
                            })();
                        }
                        const outputCtx = outputAudioContextRef.current;
                        if (!outputCtx) return;

                        const audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
                        if (audio) {
                            nextStartTimeRef.current = Math.max(
                                nextStartTimeRef.current,
                                outputCtx.currentTime
                            );
                            const buffer = await decodeAudioData(decode(audio), outputCtx, 24000, 1);
                            const source = outputCtx.createBufferSource();
                            source.buffer = buffer;
                            source.connect(outputCtx.destination);

                            source.addEventListener('ended', () => {
                                outputSourcesRef.current.delete(source);
                            });

                            source.start(nextStartTimeRef.current);
                            nextStartTimeRef.current += buffer.duration;
                            outputSourcesRef.current.add(source);
                        }

                        const interrupted = message.serverContent?.interrupted;
                        if (interrupted) {
                            for (const source of outputSourcesRef.current.values()) {
                                source.stop();
                                outputSourcesRef.current.delete(source);
                            }
                            nextStartTimeRef.current = 0;
                        }
                    },
                    onerror: (e: ErrorEvent) => {
                        console.error("Voice WebSocket Error:", e);
                        setVoiceConnectionState('error');
                        setApiError("Voice connection failed. Retrying...");
                    },
                    onclose: (e) => {
                        if (voiceConnectionState === 'connected') {
                             stopVoiceSession();
                        }
                    },
                },
                config: {
                    responseModalities: [Modality.AUDIO], outputAudioTranscription: {}, inputAudioTranscription: {},
                    speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
                    systemInstruction: systemInstruction,
                    tools: [{ functionDeclarations: [switchSkillFunctionDeclaration] }],
                },
            });
        } catch (error) {
            console.error("Error starting voice session:", error);
            setVoiceConnectionState('error');
            if (error instanceof DOMException && (error.name === 'NotAllowedError' || error.name === 'PermissionDeniedError')) {
                setApiError("I'll need microphone permission to hear you. Please try again and allow access when prompted in your browser settings.");
            } else if (error instanceof DOMException && error.name === 'NotFoundError') {
                setApiError("I couldn't find a microphone. Please make sure one is connected and enabled.");
            } else {
                setApiError("Could not start voice chat. Please check your network and try again.");
            }
            stopVoiceSession();
        }
    };

